import json, time, os
from aiohttp import web

RUNS_FILE = '/opt/trading-bot/classic/runs.json'

async def index(req):
    try:
        with open(RUNS_FILE) as f:
            runs = json.load(f)
    except:
        runs = []

    html = '''<!DOCTYPE html><html><head><meta charset="utf-8"><title>Прогоны</title>
<style>
body { font-family: -apple-system, sans-serif; background: #0f1419; color: #e0e0e0; margin: 0; padding: 20px; }
.container { max-width: 1200px; margin: 0 auto; }
h1 { font-size: 32px; margin: 0 0 20px; }
.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 20px; }
.card { background: #1a1f2e; border: 1px solid #2a3142; border-radius: 12px; padding: 20px; cursor: pointer; transition: all 0.2s; }
.card:hover { background: #202730; transform: translateY(-2px); }
.card h3 { margin: 0 0 10px; font-size: 16px; }
.card p { margin: 5px 0; font-size: 13px; color: #888; }
.stat { display: flex; justify-content: space-between; margin: 8px 0; font-size: 13px; }
.profit { color: #4ade80; }
.loss { color: #ef4444; }
.modal { display: none; position: fixed; z-index: 1000; left: 0; top: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.7); }
.modal-content { background: #0f1419; margin: 20px auto; padding: 30px; width: 90%; max-width: 900px; border-radius: 12px; border: 1px solid #2a3142; max-height: 80vh; overflow-y: auto; }
table { width: 100%; border-collapse: collapse; font-size: 13px; margin-top: 20px; }
th { background: #1a1f2e; padding: 12px; text-align: left; font-weight: 600; color: #888; border-bottom: 1px solid #2a3142; }
td { padding: 12px; border-bottom: 1px solid #2a3142; }
</style></head><body><div class="container"><h1>📊 Мои прогоны</h1><div class="grid" id="grid"></div></div>
<div id="modal" class="modal"><div class="modal-content"><span onclick="closeModal()" style="cursor:pointer; font-size:20px; float:right; color:#888;">&times;</span><div id="modalBody"></div></div></div>
<script>
const runs = ''' + json.dumps(runs) + ''';
function calcStats(t) { if (!t.length) return {total:0, win:0, profit:0}; const p = t.map(x=>x.net||0); return {total:t.length, win:p.filter(x=>x>0).length, profit:p.reduce((a,b)=>a+b,0)}; }
function showModal(r) { const t = r.trades||[]; const s = calcStats(t); let h = '<h2>' + r.name + '</h2><p>' + r.sym + ' · ' + r.cfg.tf + '</p><div class="stat"><span>Сделок</span><span>' + s.total + '</span></div><div class="stat"><span>Побед</span><span>' + s.win + '</span></div><div class="stat"><span>Прибыль</span><span class="' + (s.profit>0?'profit':'loss') + '">' + (s.profit>0?'+':'') + s.profit.toFixed(2) + '%</span></div>'; if (t.length) { h += '<table><tr><th>Вход</th><th>Выход</th><th>Результат</th></tr>'; t.forEach(x => h += '<tr><td>' + new Date(x.t_in).toLocaleString() + '</td><td>' + (x.p_out||0).toFixed(2) + '</td><td class="' + (x.net>0?'profit':'loss') + '">' + (x.net>0?'+':'') + x.net.toFixed(2) + '%</td></tr>'); h += '</table>'; } document.getElementById('modalBody').innerHTML = h; document.getElementById('modal').style.display = 'block'; }
function closeModal() { document.getElementById('modal').style.display = 'none'; }
const g = document.getElementById('grid'); runs.forEach(r => { const t = r.trades||[]; const s = calcStats(t); const c = document.createElement('div'); c.className = 'card'; c.onclick = () => showModal(r); c.innerHTML = '<h3>' + r.name + '</h3><p>' + r.sym + ' · ' + r.cfg.tf + '</p><div class="stat"><span>Сделок</span><span>' + s.total + '</span></div><div class="stat"><span>Побед</span><span>' + s.win + '</span></div><div class="stat"><span>Прибыль</span><span class="' + (s.profit>0?'profit':'loss') + '">' + (s.profit>0?'+':'') + s.profit.toFixed(2) + '%</span></div>'; g.appendChild(c); });
</script></body></html>'''
    return web.Response(text=html, content_type='text/html; charset=utf-8')

app = web.Application()
app.router.add_get('/', index)
runner = web.AppRunner(app)
import asyncio
asyncio.run(runner.setup())
site = web.TCPSite(runner, '0.0.0.0', 18092)
asyncio.run(site.start())
print('✓ Dashboard на http://localhost:18092')
await asyncio.sleep(3600)
